package com.gmail.manhle240406.project.profile;
import android.os.Bundle;
import android.content.Intent;
import android.widget.TextView;
import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import com.gmail.manhle240406.project.*;
import com.gmail.manhle240406.project.preferences.AppearanceRepository;
import com.gmail.manhle240406.project.wiring.AppServices;
import com.gmail.manhle240406.project.community.SocialViews;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
import com.google.android.material.snackbar.Snackbar;

/** Existing settings, acknowledged installation preferences; no fictitious MFA/device-management action. */
public final class EnhancedSettingsActivity extends AppCompatActivity {
 private AppServices services;private AppearanceRepository.State selection;private boolean saving;private androidx.appcompat.app.AlertDialog dialog;
 @Override protected void onCreate(Bundle state){super.onCreate(state);EdgeToEdge.enable(this);setContentView(R.layout.activity_enhanced_settings);SocialViews.insets(findViewById(R.id.enhanced_settings_root));
  services=((AniloveApplication)getApplication()).services();services.appearance.read().thenAccept(value->runOnUiThread(()->{if(!isDestroyed())selection=value;}));
  findViewById(R.id.settings_back).setOnClickListener(v->finish());
  ((TextView)findViewById(R.id.btn_setting_account)).setText(R.string.profile_title);
  findViewById(R.id.btn_setting_account).setVisibility(android.view.View.GONE);
  findViewById(R.id.btn_setting_account).setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));
  ((TextView)findViewById(R.id.btn_setting_theme)).setText(R.string.wiring_theme);((TextView)findViewById(R.id.btn_setting_language)).setText(R.string.wiring_language);((TextView)findViewById(R.id.btn_setting_security)).setText(R.string.wiring_security);
  findViewById(R.id.btn_setting_language).setOnClickListener(v->{if(selection==null||saving)return;dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.wiring_language).setSingleChoiceItems(new String[]{getString(R.string.wiring_system),"Ti\u1ebfng Vi\u1ec7t","English"},selection.language.ordinal(),(d,w)->{d.dismiss();if(w==2){dialog=new MaterialAlertDialogBuilder(this).setMessage(R.string.flow_language_pending).setPositiveButton(android.R.string.ok,null).show();return;}save(AppearanceRepository.Language.values()[w],selection.theme);}).setNegativeButton(android.R.string.cancel,null).show();});
  findViewById(R.id.btn_setting_theme).setOnClickListener(v->{if(selection==null||saving)return;dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.wiring_theme).setSingleChoiceItems(new String[]{getString(R.string.wiring_system),getString(R.string.wiring_light),getString(R.string.wiring_dark)},selection.theme.ordinal(),(d,w)->{d.dismiss();save(selection.language,AppearanceRepository.Theme.values()[w]);}).setNegativeButton(android.R.string.cancel,null).show();});
  findViewById(R.id.btn_setting_security).setOnClickListener(v->startActivity(new Intent(this,com.gmail.manhle240406.project.auth.PasswordChangeActivity.class)));
  android.view.View security=findViewById(R.id.btn_setting_security);
  android.view.ViewGroup parent=(android.view.ViewGroup)security.getParent();
  com.google.android.material.button.MaterialButton deletion=SocialViews.button(this,getString(R.string.flow_delete_account),()->startActivity(new Intent(this,AccountDeletionActivity.class)));
  deletion.setTag("account_deletion");deletion.setTextColor(com.google.android.material.color.MaterialColors.getColor(deletion,androidx.appcompat.R.attr.colorError));deletion.setStrokeColor(android.content.res.ColorStateList.valueOf(com.google.android.material.color.MaterialColors.getColor(deletion,androidx.appcompat.R.attr.colorError)));deletion.setStrokeWidth(SocialViews.dp(this,1));deletion.setBackgroundTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT));
  com.google.android.material.button.MaterialButton notifications=new com.google.android.material.button.MaterialButton(this,null,com.google.android.material.R.attr.materialButtonOutlinedStyle);notifications.setText(R.string.settings_notifications_label);formatRow(notifications);notifications.setStrokeWidth(0);notifications.setOnClickListener(v->startActivity(new Intent(this,com.gmail.manhle240406.project.notifications.NotificationSettingsActivity.class)));parent.addView(notifications,new android.widget.LinearLayout.LayoutParams(-1,-2));

  ProfileViewModel profile=new androidx.lifecycle.ViewModelProvider(this).get(ProfileViewModel.class);
  com.google.android.material.materialswitch.MaterialSwitch visibility=new com.google.android.material.materialswitch.MaterialSwitch(this);visibility.setText(R.string.feedback_public_profile);visibility.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyLarge);visibility.setTypeface(android.graphics.Typeface.create("sans",android.graphics.Typeface.NORMAL));visibility.setTextSize(16);visibility.setLetterSpacing(0);visibility.setTextColor(com.google.android.material.color.MaterialColors.getColor(visibility,com.google.android.material.R.attr.colorOnSurface));visibility.setGravity(android.view.Gravity.CENTER_VERTICAL);visibility.setPaddingRelative(SocialViews.dp(this,16),SocialViews.dp(this,12),SocialViews.dp(this,16),SocialViews.dp(this,12));visibility.setMinHeight(SocialViews.dp(this,56));parent.addView(visibility,new android.widget.LinearLayout.LayoutParams(-1,-2));
  TextView visibilityStatus=SocialViews.text(this,"",false);visibilityStatus.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyMedium);visibilityStatus.setTypeface(android.graphics.Typeface.create("sans",android.graphics.Typeface.NORMAL));visibilityStatus.setTextColor(com.google.android.material.color.MaterialColors.getColor(visibilityStatus,com.google.android.material.R.attr.colorOnSurfaceVariant));visibilityStatus.setPaddingRelative(SocialViews.dp(this,16),0,SocialViews.dp(this,16),SocialViews.dp(this,16));visibilityStatus.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);parent.addView(visibilityStatus);
  final boolean[] updating={false};profile.changes.observe(this,x->{updating[0]=true;boolean shown=profile.snapshot!=null&&profile.snapshot.control!=null&&"public".equals(profile.snapshot.control.get("visibility"));visibility.setChecked(shown);visibility.setEnabled(profile.loaded&&!profile.busy&&profile.retry==null&&profile.snapshot!=null&&profile.snapshot.control!=null);visibilityStatus.setText(profile.busy?R.string.profile_loading:profile.code!=ProfileRepository.Code.OK?R.string.profile_unavailable:shown?R.string.feedback_profile_visible:R.string.feedback_profile_hidden);updating[0]=false;});
  formatRow(deletion);deletion.setGravity(android.view.Gravity.CENTER);deletion.setTextColor(com.google.android.material.color.MaterialColors.getColor(deletion,androidx.appcompat.R.attr.colorError));android.widget.LinearLayout.LayoutParams deletionLayout=new android.widget.LinearLayout.LayoutParams(-1,-2);deletionLayout.topMargin=SocialViews.dp(this,12);parent.addView(deletion,deletionLayout);
  visibility.setOnCheckedChangeListener((button,on)->{if(updating[0])return;updating[0]=true;visibility.setChecked(!on);updating[0]=false;if(on)dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.feedback_public_profile).setMessage(R.string.profile_visibility_help).setPositiveButton(R.string.profile_show,(d,w)->profile.visibility(true)).setNegativeButton(android.R.string.cancel,null).show();else profile.visibility(false);});

 }
 private void formatRow(com.google.android.material.button.MaterialButton row){row.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyLarge);row.setTypeface(android.graphics.Typeface.create("sans",android.graphics.Typeface.NORMAL));row.setTextSize(16);row.setAllCaps(false);row.setLetterSpacing(0);row.setGravity(android.view.Gravity.START|android.view.Gravity.CENTER_VERTICAL);row.setMinHeight(SocialViews.dp(this,56));row.setMinimumHeight(SocialViews.dp(this,56));row.setPaddingRelative(SocialViews.dp(this,16),SocialViews.dp(this,12),SocialViews.dp(this,16),SocialViews.dp(this,12));row.setInsetTop(0);row.setInsetBottom(0);row.setBackgroundTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT));row.setTextColor(com.google.android.material.color.MaterialColors.getColor(row,com.google.android.material.R.attr.colorOnSurface));}
 private void save(AppearanceRepository.Language language,AppearanceRepository.Theme theme){saving=true;services.appearance.set(language,theme).whenComplete((value,error)->runOnUiThread(()->{saving=false;if(isDestroyed()||isFinishing())return;if(error!=null){Snackbar.make(findViewById(R.id.enhanced_settings_root),R.string.wiring_preference_failed,Snackbar.LENGTH_LONG).show();return;}selection=value;services.applyAppearance(value);}));}
 @Override protected void onDestroy(){if(dialog!=null)dialog.dismiss();super.onDestroy();}
}
